def descriptor(root):
    value=tomllib.loads((Path(root)/DESCRIPTOR).read_text())
    if not test_contract.exact(value,DECLARED):raise ValueError('the AN1 dispatcher claim changes its exact retained native/function/type/evidence/TEST boundary')
