def registered(item):return (item.get('mode')==MODE or item.get('path')==DESCRIPTOR or isinstance(item.get('key'),str) and item['key'].startswith(PREFIX))
def publication(link,evidence):
    return (registered(evidence) and sum(test_contract.exact(evidence,x) for x in link.evidence)==1
        and any(link.owner.key==r[2] and evidence.get('key')==PREFIX+r[0] and digest(canonical(link))==r[11] for r in IDENTITIES))
def operation(row):return dict(cmd='link',meaning=row['owner'],type='reader',to=json.loads(row['original_claim_json'])['to'],evidence=[item(row)])
def operations(ops,root):
    selected=[op for op in ops if any(registered(item) for item in op.get('evidence',()))]
    if not selected:return False
    if not test_contract.exact(selected,[operation(descriptor(root)['reference'][0])]):
        raise ValueError('the AN1 dispatcher attachment requires its one exact complete normal owning link operation')
    return True
def looks_like_access(link):
    return any(registered(e) for e in link.evidence) or (link.owner.key,link.type,link.to.key)==('cautious-iguana/tbl','reader','romantic-caiman/fn')


def native_images(root):
    """Four exact phases of one owner shared with the existing bounded withdrawals."""
    from kb import scalar_ram_leaf_withdrawal_contract as withdrawals
    row=descriptor(root)['reference'][0]
    references=[r for r in withdrawals.descriptor(root)['reference'] if r['owner']==row['owner']]
    if not references:raise ValueError('the AN1 owner lacks its exact existing withdrawal source boundary')
    original=json.loads(row['original_native_json']);withdrawn=json.loads(references[0]['proposed_native_json'])
    if any(not test_contract.exact(json.loads(r['original_native_json']),original)
            or not test_contract.exact(json.loads(r['proposed_native_json']),withdrawn) for r in references):
        raise ValueError('the AN1 and withdrawal sources disagree about their complete shared owner')
    combined=deepcopy(withdrawn)
    links=[r for r in combined['link'] if (r['type'],r['to'])==('reader','romantic-caiman/fn')]
    if len(links)!=1 or links[0].get('evidence',[])!=[]:
        raise ValueError('the existing withdrawals change the exact retained AN1 reader association')
    links[0]['evidence']=[item(row)]
    return dict(original=original,qualified=json.loads(row['proposed_native_json']),
        withdrawn=withdrawn,combined=combined)


def strip_exact_owning_append(root,document):
    """Expose only the exact preceding withdrawal image, without changing other facts."""
    images=native_images(root)
    for after,before in (('qualified','original'),('combined','withdrawn')):
        if test_contract.exact(document,images[after]):return deepcopy(images[before])
    return document
